const pptxgen = require("pptxgenjs");
const fs = require('fs');
const path = require('path');

let pres = new pptxgen();
pres.layout = 'LAYOUT_16x9'; 
pres.author = 'AI Agent';
pres.title = 'DiaTool-DPO: Enhancing Tool-Augmented LLM Dialogue via Direct Preference Optimization';

// Theme Colors
const COLORS = {
  primary: "1A237E",   // Indigo 900 (Deep Navy)
  secondary: "3F51B5", // Indigo 500 (Primary Blue)
  accent: "00BCD4",    // Cyan 500 (Bright Accent)
  bgDark: "0F172A",    // Slate 900
  bgLight: "F8FAFC",   // Slate 50
  textDark: "1E293B",  // Slate 800
  textLight: "F1F5F9", // Slate 100
  textMuted: "64748B", // Slate 500
  border: "E2E8F0"     // Slate 200
};

// --- MASTERS ---
pres.defineSlideMaster({
  title: 'TITLE_SLIDE',
  background: { color: COLORS.bgDark },
  objects: [
    { rect: { x: 0, y: 0, w: '100%', h: '100%', fill: { color: COLORS.bgDark } } },
    { rect: { x: 0, y: 0, w: '25%', h: '100%', fill: { color: COLORS.primary } } },
    { line: { x: 2.5, y: 0, w: 0, h: '100%', line: { color: COLORS.accent, width: 4 } } }
  ]
});

pres.defineSlideMaster({
  title: 'CONTENT_SLIDE',
  background: { color: COLORS.bgLight },
  objects: [
    // Top banner
    { rect: { x: 0, y: 0, w: '100%', h: 0.8, fill: { color: COLORS.primary } } },
    // Accent line under banner
    { rect: { x: 0, y: 0.8, w: '100%', h: 0.05, fill: { color: COLORS.accent } } },
    // Slide Number
    { text: { text: "DiaTool-DPO", options: { x: 0.5, y: 5.2, w: 2, h: 0.3, fontSize: 10, color: COLORS.textMuted } } },
    { placeholder: { options: { name: 'slideNum', type: 'slideNumber', x: 9, y: 5.2, w: 0.5, h: 0.3, fontSize: 10, align: 'right', color: COLORS.textMuted } } }
  ]
});

pres.defineSlideMaster({
  title: 'CONCLUSION_SLIDE',
  background: { color: COLORS.bgDark },
  objects: [
    { rect: { x: 0, y: 0, w: '100%', h: '100%', fill: { color: COLORS.primary } } },
    { rect: { x: 0, y: 0, w: '100%', h: 0.1, fill: { color: COLORS.accent } } },
    { rect: { x: 0, y: 5.5, w: '100%', h: 0.1, fill: { color: COLORS.accent } } }
  ]
});

// Helper for Slide Titles
function addSlideTitle(slide, title) {
  slide.addText(title, {
    x: 0.5, y: 0.15, w: 9, h: 0.5, fontSize: 22, fontFace: "Segoe UI",
    bold: true, color: "FFFFFF", align: "left", valign: "middle", margin: 0
  });
}

const makeShadow = () => ({ type: "outer", blur: 6, offset: 2, color: "000000", opacity: 0.10 });

// === SLIDE 1: TITLE SLIDE ===
let slide1 = pres.addSlide({ masterName: "TITLE_SLIDE" });
slide1.addText("DiaTool-DPO:", {
  x: 2.8, y: 1.8, w: 6.8, h: 0.8, fontSize: 44, fontFace: "Segoe UI",
  bold: true, color: COLORS.textLight, margin: 0
});
slide1.addText("Multi-Turn DPO for Tool-Augmented LLMs", {
  x: 2.8, y: 2.6, w: 6.8, h: 0.8, fontSize: 32, fontFace: "Segoe UI",
  bold: false, color: COLORS.accent, margin: 0
});
slide1.addText("Enhancing TA-LLM dialogue flow via direct preference optimization with automatic paired trajectory construction.", {
  x: 2.8, y: 3.8, w: 6.5, h: 1, fontSize: 18, fontFace: "Segoe UI",
  color: COLORS.textLight, margin: 0, italic: true
});

// === SLIDE 2: PROBLEM & MOTIVATION ===
let slide2 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
addSlideTitle(slide2, "SFT Alone Fails to Teach Slot-Filling and Tool Rejection");

// Left column: the problem
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.2, w: 4.2, h: 3.8, fill: { color: "FFFFFF" }, shadow: makeShadow()
});
slide2.addText("The Core Problem", {
  x: 0.7, y: 1.4, w: 3.8, h: 0.5, fontSize: 20, bold: true, color: COLORS.primary
});
slide2.addText([
  { text: "TA-LLMs trained only with Supervised Fine-Tuning (SFT) struggle with:", options: { breakLine: true } },
  { text: "Incomplete queries", options: { bullet: true, bold: true, breakLine: true, color: COLORS.secondary } },
  { text: "(missing arguments)", options: { indentLevel: 1, breakLine: true } },
  { text: "Out-of-scope requests", options: { bullet: true, bold: true, breakLine: true, color: COLORS.secondary } }
], { x: 0.7, y: 2.0, w: 3.8, h: 2.8, fontSize: 16, color: COLORS.textDark, valign: "top" });

// Right column: failure modes
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 5.1, y: 1.2, w: 4.4, h: 3.8, fill: { color: "FFFFFF" }, shadow: makeShadow()
});
slide2.addText("Three Failure Modes", {
  x: 5.3, y: 1.4, w: 4.0, h: 0.5, fontSize: 20, bold: true, color: COLORS.primary
});

slide2.addShape(pres.shapes.RECTANGLE, { x: 5.3, y: 2.0, w: 4.0, h: 0.8, fill: { color: COLORS.bgLight } });
slide2.addText("1. Failing to ask follow-up questions", { x: 5.4, y: 2.1, w: 3.8, h: 0.6, fontSize: 16, bold: true, color: COLORS.textDark, margin: 0 });

slide2.addShape(pres.shapes.RECTANGLE, { x: 5.3, y: 3.0, w: 4.0, h: 0.8, fill: { color: COLORS.bgLight } });
